export const demoMemories:Memory[]=[{"id":"mem1","member_id":"m1","title":"The mango-tree summers","story":"Every May, cousins slept on mattresses across the old house while grandparents told stories after dinner. The mango tree became the unofficial meeting point for three generations.","related_member_ids":["m1","m2","m5","m6","m9","m10"],"visibility":"member","created_at":"2026-01-03T12:00:00Z"},{"id":"mem2","member_id":"m2","title":"Her handwritten family notebook","story":"Shanta kept birthdays, marriages, addresses and tiny notes about relatives in a blue notebook. This network is imagined as the living continuation of that habit.","related_member_ids":["m2","m7","m12","m21"],"visibility":"member","created_at":"2026-02-05T12:00:00Z"},{"id":"mem3","member_id":"m9","title":"The graduation train journey","story":"Twenty-one relatives travelled overnight by train to attend one graduation. Nobody remembers the speeches, but everyone remembers the food boxes and singing on the return journey.","related_member_ids":["m9","m10","m17","m18"],"visibility":"member","created_at":"2026-03-07T12:00:00Z"},{"id":"mem4","member_id":"m12","title":"The first family business signboard","story":"The shop opened with one desk, one ledger and a hand-painted sign. Younger members still tell the story whenever someone starts something new.","related_member_ids":["m12","m11","m23","m24"],"visibility":"member","created_at":"2026-04-09T12:00:00Z"},{"id":"mem5","member_id":"m21","title":"The wedding photo everyone recreates","story":"A slightly chaotic 2004 group photo has become a family tradition: the same cousins recreate it whenever enough people are together.","related_member_ids":["m21","m22","m31","m32","m37","m38"],"visibility":"member","created_at":"2026-05-11T12:00:00Z"},{"id":"mem6","member_id":"m27","title":"Grandmother’s festival recipe","story":"The ingredient list was never written down. Four relatives reconstructed it together from memory and finally preserved it for the next generation.","related_member_ids":["m27","m28","m15","m16"],"visibility":"member","created_at":"2026-06-13T12:00:00Z"},{"id":"mem7","member_id":"m31","title":"The reunion that crossed four countries","story":"During lockdown, relatives who had not spoken in years appeared on one screen. Children met great-uncles they had only heard about.","related_member_ids":["m31","m32","m43","m44","m45"],"visibility":"member","created_at":"2026-07-15T12:00:00Z","reaction_counts":{"heart":13,"smile":8,"pray":1,"celebrate":6}},{"id":"mem8","member_id":"m37","title":"Three generations at one table","story":"A simple Sunday lunch became special when grandparents, parents and children were all present. Someone took a photo before anyone thought to pose.","related_member_ids":["m17","m18","m37","m38","m53","m54"],"visibility":"member","created_at":"2026-08-17T12:00:00Z","reaction_counts":{"heart":18,"smile":5,"pray":2,"celebrate":9}},{"id":"mem9","member_id":"m41","title":"The scholarship phone call","story":"The acceptance email arrived while the family was having tea. Within minutes, cousins across cities were celebrating in the family group.","related_member_ids":["m41","m42","m25","m26"],"visibility":"member","created_at":"2026-01-19T12:00:00Z"},{"id":"mem10","member_id":"m45","title":"Letters from London","story":"Short voice notes about rainy walks and research slowly became a family travel diary, connecting home with a new city.","related_member_ids":["m45","m46","m29","m30"],"visibility":"member","created_at":"2026-02-21T12:00:00Z"},{"id":"mem11","member_id":"m52","title":"Cousins at the finish line","story":"Training started as a fitness challenge and became a weekly reason for cousins to talk. The race medal mattered less than the habit they built together.","related_member_ids":["m51","m52","m55","m56"],"visibility":"member","created_at":"2026-03-23T12:00:00Z"},{"id":"mem12","member_id":"m58","title":"The recipe book begins","story":"The youngest generation started interviewing elders about food, rituals and the stories behind them. Each recipe is stored with the person who taught it.","related_member_ids":["m58","m57","m3","m4"],"visibility":"member","created_at":"2026-04-25T12:00:00Z","reaction_counts":{"heart":10,"smile":3,"pray":4,"celebrate":7}}];

